<template>
  <WorkspacePage back :eyebrow="isSummary ? 'Open shift' : 'Closed shift'" :title="isSummary ? 'Shift summary' : 'Closing report'" :description="description" width="default">
    <template #actions>
      <AppButton v-if="isSummary" variant="secondary" size="sm" icon="refresh" :loading="loading" @click="load">Refresh</AppButton>
      <AppButton v-if="report" variant="secondary" size="sm" icon="printer" @click="printPdf">Print</AppButton>
      <AppButton v-if="canReopen" variant="warning" size="sm" icon="refresh" :loading="reopening" @click="reopen">Reopen shift</AppButton>
    </template>

    <SkeletonList v-if="loading && !report" :rows="4" height="6rem" />

    <div v-else-if="report" class="space-y-5 pb-8">
      <AppAlert v-if="isSummary" tone="info" message="Interim report. Your shift is still open, so these figures will change until you close it." />
      <AppAlert v-if="actionError" tone="danger" :message="actionError" />
      <AppAlert
        v-if="isSummary && report.draft_orders?.length"
        tone="warning"
        :title="`${report.draft_orders.length} draft order${report.draft_orders.length === 1 ? '' : 's'} not submitted`"
      >
        Not in these figures until submitted.
        <ul class="mt-1.5 space-y-1">
          <li v-for="d in report.draft_orders" :key="d.name">
            <button type="button" class="font-semibold underline underline-offset-2" @click="router.push({ name: 'order-detail', params: { name: d.name } })">{{ d.name }}</button>
            <span class="opacity-90"> · {{ d.customer_name || d.customer }} · {{ currency }} {{ fmt(d.grand_total) }}</span>
          </li>
        </ul>
      </AppAlert>
      <AppAlert
        v-else-if="!isSummary && t.draft_orders_count"
        tone="info"
        :message="`${t.draft_orders_count} draft order${t.draft_orders_count === 1 ? ' was' : 's were'} left unsubmitted when this shift closed and ${t.draft_orders_count === 1 ? 'is' : 'are'} not in these figures.`"
      />

      <AppCard padding="sm">
        <dl class="grid grid-cols-2 gap-x-4 gap-y-2 text-xs">
          <div><dt class="text-muted">Staff</dt><dd class="font-semibold text-foreground">{{ report.shift.driver_name || report.shift.driver }}</dd></div>
          <div v-if="report.shift.van_profile"><dt class="text-muted">Profile</dt><dd class="font-semibold text-foreground">{{ report.shift.van_profile }}</dd></div>
          <div><dt class="text-muted">Opened</dt><dd class="tnum font-semibold text-foreground">{{ formatDateTime(report.shift.period_start) }}</dd></div>
          <div><dt class="text-muted">{{ isSummary ? 'As of' : 'Closed' }}</dt><dd class="tnum font-semibold text-foreground">{{ formatDateTime(isSummary ? report.generated_at : report.shift.period_end) }}</dd></div>
          <div v-if="report.shift.closed_by"><dt class="text-muted">Closed by</dt><dd class="font-semibold text-foreground">{{ report.shift.closed_by_name || report.shift.closed_by }}</dd></div>
        </dl>
      </AppCard>

      <div class="grid grid-cols-2 gap-3">
        <KpiTile label="Sales" :value="`${currency} ${fmt(t.total_sales)}`" :sub="`${t.sales_orders_count} orders · ${qty(t.total_quantity)} units`" icon="cart" tone="primary" interactive @click="openDetail('sales')" />
        <KpiTile label="Collections" :value="`${currency} ${fmt(t.total_collections)}`" :sub="`${t.payments_count} payments`" icon="wallet" tone="success" interactive @click="openDetail('collections')" />
        <KpiTile label="Expenses" :value="`${currency} ${fmt(t.total_expenses)}`" :sub="`${t.expenses_count} entries`" icon="file-text" tone="warning" interactive @click="openDetail('expenses')" />
        <KpiTile label="Expected cash" :value="`${currency} ${fmt(t.expected_cash)}`" :sub="`Float ${currency} ${fmt(t.total_opening_float)}`" icon="banknote" tone="info" interactive @click="openDetail('cash')" />
      </div>

      <!-- Tile drill-down -->
      <BottomSheet v-model="detailOpen" :title="detailTitle">
        <div class="max-h-[70vh] space-y-4 overflow-y-auto pr-1">
          <!-- Sales: orders, invoices, returns -->
          <template v-if="detail === 'sales'">
            <section>
              <p class="mb-2 text-xs font-bold uppercase tracking-wider text-muted">Sales orders · {{ docs.orders.length }}</p>
              <p v-if="!docs.orders.length" class="text-sm text-muted">No orders on this shift.</p>
              <button
                v-for="o in docs.orders"
                :key="o.name"
                type="button"
                class="flex w-full items-center justify-between gap-3 border-t border-line py-2.5 text-left first-of-type:border-0"
                @click="goTo({ name: 'order-detail', params: { name: o.name } })"
              >
                <span class="min-w-0">
                  <span class="block truncate text-sm font-semibold text-foreground">{{ o.customer_name || o.customer }}</span>
                  <span class="tnum block text-xs text-muted">{{ o.name }} · {{ formatTime(o.creation) }} · {{ qty(o.total_qty) }} units</span>
                </span>
                <span class="tnum shrink-0 text-sm font-bold text-foreground">{{ currency }} {{ fmt(o.grand_total) }}</span>
              </button>
            </section>
            <section v-if="docs.invoices.length">
              <p class="mb-2 text-xs font-bold uppercase tracking-wider text-muted">Invoices &amp; returns · {{ docs.invoices.length }}</p>
              <div v-for="i in docs.invoices" :key="i.name" class="flex items-center justify-between gap-3 border-t border-line py-2.5 first-of-type:border-0">
                <span class="min-w-0">
                  <span class="block truncate text-sm font-semibold text-foreground">{{ i.customer_name || i.customer }}</span>
                  <span class="tnum block text-xs text-muted">{{ i.name }} · {{ i.is_return ? 'Return' : i.status }}</span>
                </span>
                <span class="tnum shrink-0 text-sm font-bold" :class="i.is_return ? 'text-danger' : 'text-foreground'">{{ i.is_return ? '−' : '' }}{{ currency }} {{ fmt(i.amount) }}</span>
              </div>
            </section>
            <div class="flex items-center justify-between border-t border-line pt-3 text-sm">
              <span class="font-semibold text-foreground">Total sales</span>
              <span class="tnum font-bold text-foreground">{{ currency }} {{ fmt(t.total_sales) }}</span>
            </div>
          </template>

          <!-- Collections: payments -->
          <template v-else-if="detail === 'collections'">
            <p v-if="!docs.payments.length" class="text-sm text-muted">No payments on this shift.</p>
            <section v-for="group in paymentsByMode" :key="group.mode">
              <p class="mb-2 text-xs font-bold uppercase tracking-wider text-muted">{{ group.mode }} · {{ group.rows.length }}</p>
              <button
                v-for="p in group.rows"
                :key="p.name"
                type="button"
                class="flex w-full items-center justify-between gap-3 border-t border-line py-2.5 text-left first-of-type:border-0"
                @click="goTo({ name: 'payment-detail', params: { name: p.name } })"
              >
                <span class="min-w-0">
                  <span class="block truncate text-sm font-semibold text-foreground">{{ p.party_name || p.party }}</span>
                  <span class="tnum block text-xs text-muted">{{ p.name }} · {{ formatTime(p.creation) }}</span>
                </span>
                <span class="tnum shrink-0 text-sm font-bold text-foreground">{{ currency }} {{ fmt(p.amount) }}</span>
              </button>
              <div class="flex items-center justify-between pt-2 text-xs text-muted">
                <span>Subtotal</span><span class="tnum font-semibold">{{ currency }} {{ fmt(group.amount) }}</span>
              </div>
            </section>
            <div class="flex items-center justify-between border-t border-line pt-3 text-sm">
              <span class="font-semibold text-foreground">Total collected</span>
              <span class="tnum font-bold text-foreground">{{ currency }} {{ fmt(t.total_collections) }}</span>
            </div>
          </template>

          <!-- Expenses and deposits out of the drawer -->
          <template v-else-if="detail === 'expenses'">
            <section>
              <p class="mb-2 text-xs font-bold uppercase tracking-wider text-muted">Expenses · {{ report.expenses.length }}</p>
              <p v-if="!report.expenses.length" class="text-sm text-muted">No expenses on this shift.</p>
              <div v-for="e in report.expenses" :key="e.name" class="flex items-start justify-between gap-3 border-t border-line py-2.5 first-of-type:border-0">
                <span class="min-w-0">
                  <span class="block text-sm font-semibold text-foreground">{{ e.expense_type }}</span>
                  <span v-if="e.notes" class="block truncate text-xs text-muted">{{ e.notes }}</span>
                  <span class="block text-[11px] text-subtle">{{ e.name }}<template v-if="e.journal_entry"> · {{ e.journal_entry }}</template></span>
                </span>
                <span class="tnum shrink-0 text-sm font-bold text-foreground">{{ currency }} {{ fmt(e.amount) }}</span>
              </div>
            </section>
            <section v-if="report.deposits?.length">
              <p class="mb-2 text-xs font-bold uppercase tracking-wider text-muted">Deposited to office · {{ report.deposits.length }}</p>
              <div v-for="d in report.deposits" :key="d.name" class="flex items-start justify-between gap-3 border-t border-line py-2.5 first-of-type:border-0">
                <span class="min-w-0">
                  <span class="block text-sm font-semibold text-foreground">{{ d.expense_type }}</span>
                  <span v-if="d.notes" class="block truncate text-xs text-muted">{{ d.notes }}</span>
                  <span class="block text-[11px] text-subtle">{{ d.name }}<template v-if="d.journal_entry"> · {{ d.journal_entry }}</template></span>
                </span>
                <span class="tnum shrink-0 text-sm font-bold text-foreground">{{ currency }} {{ fmt(d.amount) }}</span>
              </div>
            </section>
            <div class="space-y-1 border-t border-line pt-3 text-sm">
              <div class="flex items-center justify-between"><span class="font-semibold text-foreground">Total expenses</span><span class="tnum font-bold text-foreground">{{ currency }} {{ fmt(t.total_expenses) }}</span></div>
              <div v-if="t.total_deposits" class="flex items-center justify-between"><span class="font-semibold text-foreground">Total deposited</span><span class="tnum font-bold text-foreground">{{ currency }} {{ fmt(t.total_deposits) }}</span></div>
            </div>
            <AppButton v-if="isSummary && store.capabilities.uses_shifts" variant="secondary" block icon="file-text" @click="goTo({ name: 'expenses' })">Record expense or deposit</AppButton>
          </template>

          <!-- Expected cash: how the drawer figure is built -->
          <template v-else-if="detail === 'cash'">
            <p class="text-xs text-muted">
              <template v-if="report.cash_mode">What the <span class="font-semibold text-foreground">{{ report.cash_mode }}</span> drawer should hold now.</template>
              <template v-else>This shift has no cash mode, so nothing is expected in the drawer.</template>
            </p>
            <div class="space-y-1.5 text-sm">
              <div v-for="line in cashLines" :key="line.label" class="flex items-center justify-between">
                <span class="text-muted">{{ line.label }}</span>
                <span class="tnum font-semibold" :class="line.sign < 0 ? 'text-danger' : 'text-foreground'">{{ line.sign < 0 ? '−' : line.sign > 0 ? '+' : '' }}{{ currency }} {{ fmt(line.amount) }}</span>
              </div>
              <div class="flex items-center justify-between border-t border-line pt-2">
                <span class="font-semibold text-foreground">Expected cash</span>
                <span class="tnum font-bold text-foreground">{{ currency }} {{ fmt(t.expected_cash) }}</span>
              </div>
            </div>
            <section v-if="otherModeRows.length">
              <p class="mb-2 text-xs font-bold uppercase tracking-wider text-muted">Other modes</p>
              <div v-for="row in otherModeRows" :key="row.mode_of_payment" class="flex items-center justify-between border-t border-line py-2 text-sm first-of-type:border-0">
                <span class="text-muted">{{ row.mode_of_payment }} <span class="text-subtle">· float {{ fmt(row.opening_amount) }}</span></span>
                <span class="tnum font-semibold text-foreground">{{ currency }} {{ fmt(row.expected_amount) }}</span>
              </div>
            </section>
            <AppButton v-if="isSummary && (store.isManager || store.capabilities.can_close_shift)" block icon="check" @click="goTo({ name: 'shift-close' })">Count and close shift</AppButton>
          </template>
        </div>
      </BottomSheet>

      <div
        v-if="!isSummary && t.net_difference !== undefined"
        class="flex items-center justify-between rounded-2xl border px-4 py-3"
        :class="varianceClass(t.net_difference)"
      >
        <div>
          <p class="text-sm font-semibold">Net variance<template v-if="t.variance_status"> · {{ t.variance_status }}</template></p>
          <p class="text-xs opacity-90">
            {{ t.net_difference === 0 ? 'Counted matches expected.' : t.net_difference > 0 ? 'More than expected.' : 'Less than expected.' }}
            <template v-if="t.variance_tolerance"> Tolerance {{ currency }} {{ fmt(t.variance_tolerance) }}.</template>
          </p>
        </div>
        <span class="tnum text-lg font-bold">{{ signed(t.net_difference) }}</span>
      </div>

      <!-- Sales -->
      <AppCard padding="lg" class="space-y-2">
        <p class="mb-1 text-sm font-semibold text-foreground">Sales</p>
        <div v-for="line in salesLines" :key="line.label" class="flex items-center justify-between text-sm">
          <span class="text-muted">{{ line.label }} <span class="text-subtle">· {{ line.count }}</span></span>
          <span class="tnum font-semibold text-foreground">{{ line.negative && line.amount ? '−' : '' }}{{ currency }} {{ fmt(line.amount) }}</span>
        </div>
        <div class="flex items-center justify-between border-t border-line pt-2 text-sm">
          <span class="font-semibold text-foreground">Net invoiced</span>
          <span class="tnum font-bold text-foreground">{{ currency }} {{ fmt(t.net_invoiced) }}</span>
        </div>
      </AppCard>

      <!-- Taxes -->
      <AppCard v-if="report.taxes?.length" padding="lg" class="space-y-2">
        <p class="mb-1 text-sm font-semibold text-foreground">Taxes on orders</p>
        <div v-for="x in report.taxes" :key="`${x.account_head}-${x.rate}`" class="flex items-center justify-between text-sm">
          <span class="min-w-0 truncate text-muted">{{ x.account_head }}<span v-if="x.rate" class="text-subtle"> · {{ qty(x.rate) }}%</span></span>
          <span class="tnum font-semibold text-foreground">{{ currency }} {{ fmt(x.amount) }}</span>
        </div>
        <div class="flex items-center justify-between border-t border-line pt-2 text-sm">
          <span class="font-semibold text-foreground">Total taxes</span>
          <span class="tnum font-bold text-foreground">{{ currency }} {{ fmt(t.total_taxes) }}</span>
        </div>
      </AppCard>

      <!-- Collections by mode -->
      <AppCard padding="lg" class="space-y-2">
        <p class="mb-1 text-sm font-semibold text-foreground">Collections by mode</p>
        <p v-if="!report.collections.length" class="text-sm text-muted">No collections.</p>
        <div v-for="c in report.collections" :key="c.mode_of_payment" class="flex items-center justify-between text-sm">
          <span class="min-w-0 truncate text-muted">{{ c.mode_of_payment }} <span class="text-subtle">· {{ c.count }}</span></span>
          <span class="tnum font-semibold text-foreground">{{ currency }} {{ fmt(c.amount) }}</span>
        </div>
      </AppCard>

      <!-- Cash reconciliation -->
      <AppCard padding="lg" class="space-y-3">
        <p class="text-sm font-semibold text-foreground">Cash reconciliation</p>
        <div v-for="row in report.payment_reconciliation" :key="row.mode_of_payment" class="space-y-2 rounded-2xl border border-border p-3">
          <div class="flex items-center justify-between">
            <span class="text-sm font-bold text-foreground">{{ row.mode_of_payment }}</span>
            <span v-if="row.difference" class="tnum text-xs font-bold" :class="row.difference > 0 ? 'text-success' : 'text-danger'">{{ signed(row.difference) }}</span>
          </div>
          <div class="grid gap-2 text-center text-xs" :class="isSummary ? 'grid-cols-2' : 'grid-cols-3'">
            <div class="rounded-xl bg-muted/40 py-1.5">
              <p class="opacity-60">Opening</p>
              <p class="tnum font-semibold text-foreground">{{ fmt(row.opening_amount) }}</p>
            </div>
            <div class="rounded-xl bg-muted/40 py-1.5">
              <p class="opacity-60">Expected</p>
              <p class="tnum font-semibold text-foreground">{{ fmt(row.expected_amount) }}</p>
            </div>
            <div v-if="!isSummary" class="rounded-xl bg-muted/40 py-1.5">
              <p class="opacity-60">Counted</p>
              <p class="tnum font-semibold text-foreground">{{ fmt(row.closing_amount ?? 0) }}</p>
            </div>
          </div>
        </div>
      </AppCard>

      <!-- Expenses -->
      <AppCard padding="lg" class="space-y-2">
        <p class="mb-1 text-sm font-semibold text-foreground">Expenses</p>
        <p v-if="!report.expenses.length" class="text-sm text-muted">No expenses.</p>
        <div v-for="e in report.expenses" :key="e.name" class="flex items-start justify-between gap-3 text-sm">
          <div class="min-w-0">
            <p class="text-foreground">{{ e.expense_type }}</p>
            <p v-if="e.notes" class="truncate text-xs text-muted">{{ e.notes }}</p>
            <p v-if="e.journal_entry" class="text-[11px] text-subtle">{{ e.journal_entry }}</p>
          </div>
          <span class="tnum font-semibold text-foreground">{{ currency }} {{ fmt(e.amount) }}</span>
        </div>
      </AppCard>

      <!-- Deposits to office -->
      <AppCard v-if="report.deposits?.length" padding="lg" class="space-y-2">
        <p class="mb-1 text-sm font-semibold text-foreground">Cash deposited to office</p>
        <div v-for="d in report.deposits" :key="d.name" class="flex items-start justify-between gap-3 text-sm">
          <div class="min-w-0">
            <p class="text-foreground">{{ d.expense_type }}</p>
            <p v-if="d.notes" class="truncate text-xs text-muted">{{ d.notes }}</p>
            <p v-if="d.journal_entry" class="text-[11px] text-subtle">{{ d.journal_entry }}</p>
          </div>
          <span class="tnum font-semibold text-foreground">{{ currency }} {{ fmt(d.amount) }}</span>
        </div>
        <div class="flex items-center justify-between border-t border-line pt-2 text-sm font-bold text-foreground">
          <span>Total deposited</span><span class="tnum">{{ currency }} {{ fmt(t.total_deposits) }}</span>
        </div>
      </AppCard>

      <!-- Items -->
      <AppCard padding="lg" class="space-y-3">
        <div>
          <p class="text-sm font-semibold text-foreground">Items</p>
          <p class="text-xs text-muted">In stock UOM. Amounts net of order discounts, before tax.</p>
        </div>
        <p v-if="!report.items.length" class="text-sm text-muted">No items sold or returned.</p>
        <div v-for="i in report.items" :key="i.item_code" class="flex items-start justify-between gap-3 border-t border-line pt-3 first-of-type:border-0 first-of-type:pt-0">
          <div class="min-w-0">
            <p class="truncate text-sm font-semibold text-foreground">{{ i.item_name || i.item_code }}</p>
            <p class="tnum text-xs text-muted">
              Sold {{ qty(i.sold_qty) }}<template v-if="i.returned_qty"> · Returned {{ qty(i.returned_qty) }}</template>
            </p>
          </div>
          <div class="shrink-0 text-right">
            <p class="tnum text-sm font-bold text-foreground">{{ qty(i.net_qty) }} {{ i.uom }}</p>
            <p class="tnum text-xs text-muted">{{ currency }} {{ fmt(i.sold_amount - i.returned_amount) }}</p>
          </div>
        </div>
      </AppCard>

      <AppCard v-if="report.shift.notes" padding="lg">
        <p class="mb-1 text-sm font-semibold text-foreground">Notes</p>
        <p class="whitespace-pre-line text-sm text-muted">{{ report.shift.notes }}</p>
      </AppCard>
    </div>

    <div v-else class="space-y-4">
      <AppAlert tone="danger" :message="error || 'Report unavailable.'" />
      <AppButton v-if="isSummary" variant="secondary" icon="play-circle" @click="router.push({ name: 'shift-open' })">Open a shift</AppButton>
    </div>
  </WorkspacePage>
</template>

<script setup lang="ts">
import { computed, ref, watch } from 'vue';
import { useRoute, useRouter } from 'vue-router';
import * as api from '../api/frappe';
import { useSessionStore } from '../stores/session';
import type { ShiftReport } from '../types';
import WorkspacePage from '../components/WorkspacePage.vue';
import { AppCard, AppButton, AppAlert, BottomSheet, KpiTile, SkeletonList } from '../components/ui';

const route = useRoute();
const router = useRouter();
const store = useSessionStore();
const currency = computed(() => store.currencyDisplay);

const isSummary = computed(() => route.name === 'shift-summary');
const report = ref<ShiftReport | null>(null);
const loading = ref(true);
const error = ref('');
const actionError = ref('');
const reopening = ref(false);
const canReopen = computed(() => !isSummary.value && !!report.value?.shift.closing_shift && store.isManager);

const reopen = async () => {
  const r = report.value;
  if (!r?.shift.closing_shift) return;
  if (!window.confirm(`Reopen ${r.shift.driver_name}'s shift from ${formatDate(r.shift.shift_date)}? The closing ${r.shift.closing_shift} is cancelled and the shift continues until it is closed again.`)) return;
  reopening.value = true;
  actionError.value = '';
  try {
    const opening = await api.reopenShift(r.shift.closing_shift);
    router.replace({ name: 'shift-summary', query: { opening: opening.name } });
  } catch (e: any) {
    actionError.value = e?.message || 'Could not reopen the shift.';
  } finally {
    reopening.value = false;
  }
};

const t = computed(() => report.value!.totals);
const description = computed(() =>
  isSummary.value
    ? 'Everything on your open shift so far. Running it does not close the shift.'
    : report.value
      ? `Final figures for the shift on ${formatDate(report.value.shift.shift_date)}.`
      : 'Final figures for a closed shift.',
);
// ─── Tile drill-down ────────────────────────────────────────────────────────
type DetailKind = 'sales' | 'collections' | 'expenses' | 'cash';
const detail = ref<DetailKind | null>(null);
const detailOpen = computed({ get: () => detail.value !== null, set: (v: boolean) => { if (!v) detail.value = null; } });
const openDetail = (kind: DetailKind) => { detail.value = kind; };
const goTo = (to: Parameters<typeof router.push>[0]) => { detail.value = null; router.push(to); };
const detailTitle = computed(
  () => ({ sales: 'Sales on this shift', collections: 'Collections on this shift', expenses: 'Expenses & deposits', cash: 'Expected cash' })[detail.value || 'sales'],
);
const docs = computed(() => report.value?.documents || { orders: [], invoices: [], payments: [] });
const paymentsByMode = computed(() => {
  const groups: Record<string, { mode: string; rows: typeof docs.value.payments; amount: number }> = {};
  for (const p of docs.value.payments) {
    const g = (groups[p.mode_of_payment] ||= { mode: p.mode_of_payment, rows: [], amount: 0 });
    g.rows.push(p);
    g.amount += p.amount;
  }
  return Object.values(groups);
});
const cashRow = computed(() => report.value?.payment_reconciliation.find((r) => r.mode_of_payment === report.value?.cash_mode) || null);
const otherModeRows = computed(() => (report.value?.payment_reconciliation || []).filter((r) => r.mode_of_payment !== report.value?.cash_mode));
const cashLines = computed(() => {
  const r = report.value;
  if (!r || !r.cash_mode) return [];
  const cashCollections = r.collections.find((c) => c.mode_of_payment === r.cash_mode)?.amount || 0;
  return [
    { label: 'Opening float', amount: cashRow.value?.opening_amount || 0, sign: 0 },
    { label: `${r.cash_mode} collections`, amount: cashCollections, sign: 1 },
    { label: 'Expenses', amount: r.totals.total_expenses, sign: -1 },
    { label: 'Deposited to office', amount: r.totals.total_deposits, sign: -1 },
  ];
});
const formatTime = (ts: string | null) => {
  const d = parseTs(ts);
  return d && !Number.isNaN(d.getTime()) ? d.toLocaleTimeString(undefined, { hour: '2-digit', minute: '2-digit' }) : '';
};

const salesLines = computed(() => [
  { label: 'Sales orders', count: t.value.sales_orders_count, amount: t.value.total_sales, negative: false },
  { label: 'Net before tax', count: `${qty(t.value.total_quantity)} units`, amount: t.value.net_total, negative: false },
  { label: 'Taxes', count: report.value?.taxes?.length || 0, amount: t.value.total_taxes, negative: false },
  { label: 'Sales invoices', count: t.value.invoices_count, amount: t.value.invoiced_total, negative: false },
  { label: 'Returns', count: t.value.returns_count, amount: t.value.returns_total, negative: true },
]);

const fmt = (n?: number | null) => (n || 0).toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 });
const qty = (n: number) => (n || 0).toLocaleString(undefined, { maximumFractionDigits: 3 });
const signed = (n: number) => `${n > 0 ? '+' : n < 0 ? '−' : ''}${currency.value} ${fmt(Math.abs(n))}`;
const varianceClass = (n: number) =>
  n === 0
    ? 'border-border bg-muted/40 text-foreground'
    : n > 0
      ? 'border-success/25 bg-success/10 text-success'
      : 'border-danger/25 bg-danger/10 text-danger';
const parseTs = (ts: string | null) => (ts ? new Date(ts.replace(' ', 'T')) : null);
const formatDateTime = (ts: string | null) => {
  const d = parseTs(ts);
  return d && !Number.isNaN(d.getTime())
    ? d.toLocaleString(undefined, { day: '2-digit', month: 'short', hour: '2-digit', minute: '2-digit' })
    : '—';
};
const formatDate = (s: string) => {
  const d = new Date(`${s}T00:00:00`);
  return Number.isNaN(d.getTime()) ? s : d.toLocaleDateString(undefined, { day: 'numeric', month: 'short', year: 'numeric' });
};

const load = async () => {
  loading.value = true;
  error.value = '';
  try {
    report.value = isSummary.value
      ? await api.getShiftSummary((route.query.opening as string) || undefined)
      : await api.getClosingReport(route.params.name as string);
  } catch (e: any) {
    report.value = null;
    error.value = e?.message || 'Could not load the report.';
  } finally {
    loading.value = false;
  }
};

const printPdf = () => {
  if (!report.value) return;
  if (isSummary.value) api.downloadPdf('Sales Shift Opening', report.value.shift.opening_shift, 'Sales Shift Summary');
  else api.downloadPdf('Sales Shift Closing', report.value.shift.closing_shift!, 'Sales Shift Closing Report');
};

watch(() => route.fullPath, load, { immediate: true });
</script>
